"""`Gag`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'Gag'


def build(lib):
    t = lib.new_material(NAME, props={})

    t.node('ShaderNodeOutputMaterial', 'Material Output', props={
        'location': (600.0, 0.0),
    })
    t.node('ShaderNodeGroup', 'gag.output', props={
        'node_tree': lib.group('.Gag output'),
        'location': (350.0, 0.0),
        'label': 'gag.output',
    })
    t.node('ShaderNodeValue', 'gag.frame', props={
        'location': (-900.0, 200.0),
        'label': 'gag.frame',
    })
    t.node('ShaderNodeValue', 'gag.choice', props={
        'location': (-900.0, 0.0),
        'label': 'gag.choice',
    })

    t.link('gag.output', 'Shader', 'Material Output', 'Surface')

    t.driver('nodes["gag.frame"].outputs[0].default_value', 'frame')
    return t
